export function evaluate({ inputs, time }) {
  const U = Number(inputs.launchSpeed);
  const g = Number(inputs.gravity);
  const tTop = U / g;
  const tEnd = 2 * U / g;
  const t = sdk.clamp(Number(time) || 0, 0, tEnd);
  const apexTime = tTop;
  const apexHeight = U * U / (2 * g);
  const tossedVelocity = U - g * t;
  const tossedAcceleration = -g;
  const tossedHeight = Math.max(0, U * t - g * t * t / 2);
  const released = t >= tTop - 1e-9;
  const tau = Math.max(0, t - tTop);
  const dropVelocity = released ? -g * tau : 0;
  const dropAcceleration = released ? -g : 0;
  const dropHeight = released ? Math.max(0, apexHeight - g * tau * tau / 2) : apexHeight;

  const groundY = 330;
  const axisLen = 220;
  const ppm = axisLen / 2.2;
  const yOf = (h) => groundY - h * ppm;
  const vScale = 15;
  const aScale = 5;
  const arrowOff = 44;
  const clean = (v) => (Math.abs(v) < 0.005 ? 0 : v);
  const sgn = (v, d) => { const c = clean(v); const s = sdk.format(c, d); return c > 0 ? '+' + s : s; };

  let tossState;
  if (t <= 1e-9) tossState = 'At launch';
  else if (Math.abs(t - tTop) < 1e-6) tossState = 'At the top';
  else if (t < tTop) tossState = 'Rising';
  else if (t < tEnd - 1e-9) tossState = 'Falling';
  else tossState = 'At launch height';
  let dropState;
  if (!released) dropState = 'Held in place';
  else if (t >= tEnd - 1e-9) dropState = 'At launch height';
  else if (t < tTop + 0.03) dropState = 'Just released';
  else dropState = 'Falling together';

  const objects = [];
  objects.push(sdk.axis('heightAxis', { x: 80, y: groundY, length: axisLen, orientation: 'y', min: 0, max: 2.2, label: 'Height', unit: 'm' }));

  const lanes = [
    { id: 'toss', x: 100, title: 'Toss', state: tossState, role: 'input', h: tossedHeight, v: tossedVelocity, a: tossedAcceleration },
    { id: 'drop', x: 368, title: 'Drop', state: dropState, role: 'output', h: dropHeight, v: dropVelocity, a: dropAcceleration }
  ];
  for (const L of lanes) {
    objects.push(...sdk.panel({ id: L.id + 'Lane', x: L.x, y: 34, w: 262, h: 48, title: L.title, state: L.state, role: L.role }));
    const bx = L.x + 75;
    objects.push(...sdk.groundMark(L.id + 'Launch', bx, groundY + 11, 50, 'Launch'));
    if (released) {
      objects.push(sdk.circle(L.id + 'Outline', bx, yOf(apexHeight), 20, { role: 'neutral', opacity: 0.3 }));
    }
    const by = yOf(L.h);
    objects.push(sdk.circle(L.id + 'Ball', bx, by, 20, { role: L.role }));
    objects.push(...sdk.vector(L.id + 'Vel', { x: bx - arrowOff, y: by }, { value: L.v, direction: 'up' }, { scale: vScale, label: 'v', role: 'input' }));
    objects.push(...sdk.vector(L.id + 'Acc', { x: bx + arrowOff, y: by }, { value: L.a, direction: 'up' }, { scale: aScale, label: 'a', role: 'warning' }));
    const cy = sdk.clamp(by - 24, 100, 330);
    objects.push(...sdk.callout(L.x + 135, cy, ['v = ' + sgn(L.v, 2) + ' m/s', 'a = ' + sgn(L.a, 1) + ' m/s²'], { id: L.id + 'Callout', role: L.role }));
  }
  objects.push(...sdk.gate('gate', 368 + 75, yOf(apexHeight) + 12, { open: released, w: 36, label: 'Gate' }));

  const q = {
    launchSpeed: U, gravity: g, apexTime, apexHeight,
    tossedVelocity: clean(tossedVelocity), tossedAcceleration, tossedHeight,
    dropVelocity: clean(dropVelocity), dropAcceleration, dropHeight
  };
  return {
    frame: {
      width: 640, height: 420, objects,
      readouts: [
        { id: 'tossedVelocity', value: q.tossedVelocity },
        { id: 'tossedAcceleration', value: tossedAcceleration },
        { id: 'dropVelocity', value: q.dropVelocity },
        { id: 'dropAcceleration', value: dropAcceleration }
      ]
    },
    quantities: q
  };
}
